create table if not exists public.tipos_productos (
  "Id_Tipos_Productos" integer generated by default as identity primary key,
  "Descripcion" varchar(100) not null unique
);

create table if not exists public.productos (
  "Id_Productos" integer generated by default as identity primary key,
  "Descripcion" varchar(150) not null unique,
  "PrecioDeCosto" numeric(18,2) not null,
  "PrecioDeVenta" numeric(18,2) not null,
  "Activo" boolean not null default true,
  "StockActual" numeric(18,2) not null default 0,
  constraint productos_precios_y_stock_no_negativos check ("PrecioDeCosto" >= 0 and "PrecioDeVenta" >= 0 and "StockActual" >= 0)
);

create table if not exists public.productos_tipos (
  "Id_Productos" integer not null references public.productos("Id_Productos") on delete cascade,
  "Id_Tipos_Productos" integer not null references public.tipos_productos("Id_Tipos_Productos") on delete restrict,
  primary key ("Id_Productos", "Id_Tipos_Productos")
);

insert into public.tipos_productos ("Descripcion")
values ('Servicio'), ('Producto'), ('Insumo')
on conflict ("Descripcion") do nothing;
